begin;
create table if not exists public.drag_race_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,mode text not null check(mode in('SEASON_SIMULATOR','TRACK_RECORD','GUESS_THEM_ALL','GUESS_THE_LIPSYNC','SLAYOFF','LIPSYNC_FOR_YOUR_LIFE')),status text not null default 'ACTIVE' check(status in('ACTIVE','COMPLETED','ABANDONED')),config jsonb not null default '{}'::jsonb check(jsonb_typeof(config)='object'),state jsonb not null default '{}'::jsonb check(jsonb_typeof(state)='object'),summary jsonb,started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.drag_race_results(id uuid primary key default gen_random_uuid(),session_id uuid not null unique references public.drag_race_sessions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,mode text not null check(mode in('SEASON_SIMULATOR','TRACK_RECORD','GUESS_THEM_ALL','GUESS_THE_LIPSYNC','SLAYOFF','LIPSYNC_FOR_YOUR_LIFE')),score integer not null default 0,wins integer not null default 0,losses integer not null default 0,errors integer not null default 0,hints integer not null default 0,duration_seconds integer not null default 0,accuracy numeric(7,4),summary jsonb not null,completed_at timestamptz not null default now());
create index if not exists drag_race_sessions_user_idx on public.drag_race_sessions(user_id,created_at desc);
create index if not exists drag_race_results_mode_idx on public.drag_race_results(mode,score desc,completed_at);
alter table public.drag_race_sessions enable row level security;alter table public.drag_race_sessions force row level security;
alter table public.drag_race_results enable row level security;alter table public.drag_race_results force row level security;
revoke all on public.drag_race_sessions,public.drag_race_results from anon,authenticated;
grant select on public.drag_race_sessions,public.drag_race_results to authenticated;
create policy drag_race_sessions_owner_read on public.drag_race_sessions for select to authenticated using(private.is_approved_user() and user_id=(select auth.uid()));
create policy drag_race_results_owner_read on public.drag_race_results for select to authenticated using(private.is_approved_user() and user_id=(select auth.uid()));
create or replace function public.drag_race_create_session(p_mode text,p_config jsonb default '{}'::jsonb,p_state jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_id uuid;begin
if auth.uid() is null or not private.is_approved_user() then raise exception 'Account non autorizzato';end if;
if p_mode not in('SEASON_SIMULATOR','TRACK_RECORD','GUESS_THEM_ALL','GUESS_THE_LIPSYNC','SLAYOFF','LIPSYNC_FOR_YOUR_LIFE') then raise exception 'Modalità non valida';end if;
if jsonb_typeof(coalesce(p_config,'{}'::jsonb))<>'object' or jsonb_typeof(coalesce(p_state,'{}'::jsonb))<>'object' or octet_length(coalesce(p_config,'{}'::jsonb)::text)>32000 or octet_length(coalesce(p_state,'{}'::jsonb)::text)>64000 then raise exception 'Configurazione o stato non valido';end if;
insert into public.drag_race_sessions(user_id,mode,config,state) values(auth.uid(),p_mode,coalesce(p_config,'{}'::jsonb),coalesce(p_state,'{}'::jsonb)) returning id into v_id;return v_id;end;$$;
revoke all on function public.drag_race_create_session(text,jsonb,jsonb) from public,anon;grant execute on function public.drag_race_create_session(text,jsonb,jsonb) to authenticated;
create or replace function public.drag_race_update_session(p_session_id uuid,p_state jsonb,p_status text default 'ACTIVE',p_summary jsonb default null) returns boolean language plpgsql security definer set search_path=public,private,pg_temp as $$
declare v_session public.drag_race_sessions%rowtype;v_summary jsonb;begin
if auth.uid() is null or not private.is_approved_user() then raise exception 'Account non autorizzato';end if;
if p_session_id is null or jsonb_typeof(coalesce(p_state,'{}'::jsonb))<>'object' or octet_length(coalesce(p_state,'{}'::jsonb)::text)>64000 or p_status not in('ACTIVE','COMPLETED','ABANDONED') then raise exception 'Aggiornamento sessione non valido';end if;
select * into v_session from public.drag_race_sessions where id=p_session_id and user_id=auth.uid() for update;
if not found or v_session.status<>'ACTIVE' then raise exception 'Sessione non disponibile';end if;
if p_status in('COMPLETED','ABANDONED') and jsonb_typeof(coalesce(p_summary,'{}'::jsonb))<>'object' then raise exception 'Riepilogo finale non valido';end if;
v_summary:=coalesce(p_summary,'{}'::jsonb);
update public.drag_race_sessions set state=coalesce(p_state,'{}'::jsonb),status=p_status,summary=case when p_status='ACTIVE' then summary else v_summary end,completed_at=case when p_status='ACTIVE' then null else now() end,updated_at=now() where id=p_session_id;
if p_status='COMPLETED' then insert into public.drag_race_results(session_id,user_id,mode,score,wins,losses,errors,hints,duration_seconds,accuracy,summary) values(p_session_id,auth.uid(),v_session.mode,greatest(0,coalesce((v_summary->>'completed')::integer,(v_summary->>'wins')::integer,0)),greatest(0,coalesce((v_summary->>'completed')::integer,(v_summary->>'wins')::integer,0)),greatest(0,coalesce((v_summary->>'skipped')::integer,(v_summary->>'losses')::integer,0)),greatest(0,coalesce((v_summary->>'errors')::integer,0)),greatest(0,coalesce((v_summary->>'hints')::integer,0)),greatest(0,coalesce((v_summary->>'durationSeconds')::integer,0)),nullif(v_summary->>'percentage','')::numeric,v_summary);end if;return true;end;$$;
revoke all on function public.drag_race_update_session(uuid,jsonb,text,jsonb) from public,anon;grant execute on function public.drag_race_update_session(uuid,jsonb,text,jsonb) to authenticated;
commit;